import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.kOe0DhAP.js";const u=JSON.parse('{"title":"服务通信与消息流转","description":"理解同步响应、异步事件与实时推送各自能证明什么。","frontmatter":{"title":"服务通信与消息流转","description":"理解同步响应、异步事件与实时推送各自能证明什么。"},"headers":[],"relativePath":"architecture/communication.md","filePath":"architecture/communication.md"}'),o={name:"architecture/communication.md"};function i(c,t,n,h,l,s){return e(),d("div",null,[...t[0]||(t[0]=[r('<div class="doc-eyebrow">系统架构 / TGEX KNOWLEDGE BASE</div><h1 id="服务通信与消息流转" tabindex="-1">服务通信与消息流转 <a class="header-anchor" href="#服务通信与消息流转" aria-label="Permalink to &quot;服务通信与消息流转&quot;">​</a></h1><div class="doc-lead">理解同步响应、异步事件与实时推送各自能证明什么。</div><h2 id="通信方式" tabindex="-1">通信方式 <a class="header-anchor" href="#通信方式" aria-label="Permalink to &quot;通信方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>适用场景</th><th>主要失败方式</th></tr></thead><tbody><tr><td>HTTP</td><td>用户提交操作、后台配置、查询</td><td>网络断开、网关超时、鉴权失败</td></tr><tr><td>Dubbo</td><td>业务域之间调用</td><td>超时、调用失败、版本不匹配</td></tr><tr><td>消息</td><td>成交结果、异步处理、数据同步</td><td>重复、延迟、乱序、消费失败</td></tr><tr><td>WebSocket / Netty</td><td>行情与业务通知</td><td>断线、丢失增量、连接迁移</td></tr></tbody></table><h2 id="超时的含义" tabindex="-1">超时的含义 <a class="header-anchor" href="#超时的含义" aria-label="Permalink to &quot;超时的含义&quot;">​</a></h2><p>超时只说明调用方没有及时得到结果，不能证明服务端没有执行。对下单、划转、提现和结算，应通过业务编号查询既有结果，再决定重试。</p><h2 id="设计目标" tabindex="-1">设计目标 <a class="header-anchor" href="#设计目标" aria-label="Permalink to &quot;设计目标&quot;">​</a></h2><p>异步消费需要去重、可追踪和可恢复。发送成功、消费成功与业务落账是不同阶段。业务文档应注明每条事件的生产者、消费者、唯一编号及失败后的查询入口。</p>',9)])])}const _=a(o,[["render",i]]);export{u as __pageData,_ as default};
